    def is_num(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def is_pos(v):
        return isinstance(v, (list, tuple)) and len(v) == 2 and is_num(v[0]) and is_num(v[1])

    def to_pos(v):
        if is_pos(v):
            return [v[0], v[1]]
        if isinstance(v, dict):
            if is_num(v.get("x")) and is_num(v.get("y")):
